    private(set) var error: ProductActions.ActionError?

    mutating func save(using actions: ProductActions) -> Bool {
        switch actions.create(from: draft) {
        case .success:
            error = nil
            return true
        case .failure(let failure):
            error = failure
            return false
        }
    }

mutating func save(using actions: ProductActions) -> Bool {
